CREATE TABLE orders (order_id INT, merchant_id INT, base_amount DECIMAL(10,2));
CREATE TABLE order_discounts (discount_id INT, order_id INT, amount DECIMAL(10,2));
CREATE TABLE order_shipments (shipment_id INT, order_id INT, shipping_fee DECIMAL(10,2));

